/**
 * Bundles `templates/<id>/` into the Worker as `src/generated/templates.ts`: every file of every
 * launch template as a UTF-8 string (lockfiles included; node_modules, build output and local
 * state excluded), plus a content digest per template.
 *
 *   pnpm --filter @app/platform bundle-templates [--check]
 *
 * `--check` writes nothing and exits 1 when the generated file is stale (tests and
 * `deploy:prepare` run the writer, so a template edit always reaches the Worker).
 */
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
import { existsSync, readdirSync, readFileSync, statSync, writeFileSync } from "node:fs";
import { join, relative, sep } from "node:path";

const ROOT = join(import.meta.dirname, "..", "..", "..");
const TEMPLATES_DIR = join(ROOT, "templates");
const OUT = join(import.meta.dirname, "..", "src", "generated", "templates.ts");

/** Directories never shipped: dependencies, build output, local tool state. */
const SKIP_DIRS = new Set(["node_modules", "dist", ".wrangler", ".turbo", "coverage", ".git"]);
const SKIP_FILES = new Set([".DS_Store", ".dev.vars"]);
/** Above this the generated module is no longer committed (see the file header). */
const MAX_BYTES = 300 * 1024;

function walk(dir: string, base: string, out: Record<string, string>): void {
  for (const name of readdirSync(dir).sort()) {
    const path = join(dir, name);
    const st = statSync(path);
    if (st.isDirectory()) {
      if (!SKIP_DIRS.has(name)) walk(path, base, out);
      continue;
    }
    if (!st.isFile() || SKIP_FILES.has(name)) continue;
    const bytes = readFileSync(path);
    const text = bytes.toString("utf8");
    if (!Buffer.from(text, "utf8").equals(bytes) || text.includes("\u0000")) {
      throw new Error(`${relative(ROOT, path)} is not UTF-8 text; templates must be text files`);
    }
    out[relative(base, path).split(sep).join("/")] = text;
  }
}

function digest(files: Record<string, string>): string {
  const h = createHash("sha256");
  for (const path of Object.keys(files).sort()) h.update(`${path}\0${files[path]}\0`);
  return h.digest("hex");
}

export function bundleTemplates(): string {
  const ids = readdirSync(TEMPLATES_DIR)
    .filter((n) => existsSync(join(TEMPLATES_DIR, n, "template.json")))
    .sort();
  const templates: Record<string, Record<string, string>> = {};
  for (const id of ids) {
    const files: Record<string, string> = {};
    walk(join(TEMPLATES_DIR, id), join(TEMPLATES_DIR, id), files);
    templates[id] = files;
  }
  const digests = Object.fromEntries(ids.map((id) => [id, digest(templates[id] ?? {})]));
  return [
    "// Generated by apps/platform/scripts/bundle-templates.ts from templates/. Do not edit.",
    "// Regenerate: pnpm --filter @app/platform bundle-templates",
    "// biome-ignore-all lint/suspicious/noTemplateCurlyInString: file contents, not template literals",
    "",
    "/** Template id → repo path → file content (UTF-8). */",
    `export const TEMPLATE_FILES: Readonly<Record<string, Readonly<Record<string, string>>>> = ${JSON.stringify(templates, null, 1)};`,
    "",
    "/** Template id → SHA-256 over its sorted (path, content) pairs. */",
    `export const TEMPLATE_DIGESTS: Readonly<Record<string, string>> = ${JSON.stringify(digests, null, 1)};`,
    "",
  ].join("\n");
}

/** The repo's formatter, so the committed module passes `biome check` as generated. */
function format(source: string): string {
  const biome = join(ROOT, "node_modules", ".bin", "biome");
  return execFileSync(biome, ["format", `--stdin-file-path=${OUT}`], {
    input: source,
    encoding: "utf8",
    maxBuffer: 16 * 1024 * 1024,
  });
}

const text = format(bundleTemplates());
const bytes = Buffer.byteLength(text);
if (bytes > MAX_BYTES) {
  console.warn(
    `templates.ts is ${bytes} bytes (> ${MAX_BYTES}): stop committing it and gitignore src/generated/`,
  );
}
const current = existsSync(OUT) ? readFileSync(OUT, "utf8") : null;
if (process.argv.includes("--check")) {
  if (current !== text) {
    console.error("src/generated/templates.ts is out of date: run bundle-templates");
    process.exit(1);
  }
  console.log("templates.ts is up to date");
} else if (current !== text) {
  writeFileSync(OUT, text);
  console.log(`wrote src/generated/templates.ts (${bytes} bytes)`);
} else {
  console.log(`templates.ts is up to date (${bytes} bytes)`);
}
